fullText:
#divbt { text-align: right }

h1 {
    position : relative;
    left : 75px;
    width : 95%;
    height : 60px;
    padding : 20px 0px 0px 0px; 
}

img {
    width : 70px;
    height : 80px;
    position : fixed;
    margin: 0px 0px 20px 0px   ;
}

nav {
    height : 450px;
    position : fixed;
    width : 30%;
}

section {
        width : 70%;
        height : 450px;
        position : relative;
        left : 25%;
        border-radius : 3px;
        box-shadow : 2px 5px 10px black;
}

iframe {
        width : 100%;
        height : 100%;
}

footer { margin : 20px 0px 0px 0px; }

label {
	   width: 180px;
       display: inline-block  ;
       margin: 10px;
}

legend { font-weight: bold ;}

input[type="text"] { width: 172px; }

